{
  "title": "Services and Data Processing Agreement",
  "planted": [
    {
      "slot": "p1",
      "text": "The Vendor shall archive and preserve all processed data continuously for an indefinite operational period within its historical database repositories, ensuring that records remain accessible perpetually for future analytical continuity regardless of whether the primary business engagement has concluded."
    },
    {
      "slot": "p2",
      "text": "In the event of any verified security incident, unauthorized intrusion, or data breach affecting the processed information, the Vendor shall notify the Customer in writing within twenty-four hours of confirmation, enabling the Customer to fulfill its reporting obligations to the relevant regulatory authority within seventy-two hours."
    },
    {
      "slot": "p3",
      "text": "The Customer reserves the right to conduct an annual on-site assessment of the Vendor's technical infrastructure and operational safeguards, provided that the Customer delivers a written notice thirty days in advance of such inspection."
    },
    {
      "slot": "p4",
      "text": "The Vendor shall utilize the designated information strictly in connection with the performance of the technical services outlined herein, subject to such adjustments as may be reasonably required for operational optimization and general system improvements."
    }
  ],
  "neutral": [
    "Definitions: In this Agreement, Customer refers to Al-Faris Digital Solutions LLC, and Vendor refers to Zenith Technology Partners, and Services refers to the cloud hosting and maintenance tasks detailed in the Statement of Work.",
    "Term and Termination: This Agreement shall commence on the effective date and shall continue for an initial period of twelve months, renewable automatically unless either party provides sixty days written notice of non-renewal.",
    "Fees and Payment: The Customer shall remit payment for all undisputed invoices within thirty days of issuance, utilizing the electronic wire transfer instructions provided by the Vendor.",
    "Intellectual Property: All proprietary software, source code, documentation, and pre-existing materials developed prior to or independently of this Agreement shall remain the exclusive property of the originating party.",
    "Delivery: The Vendor shall deploy the agreed software modules and configuration items to the staging environment according to the milestone schedule agreed upon by both designated project managers.",
    "Liability: Neither party shall be liable to the other for any indirect, incidental, consequential, or punitive damages arising out of or in connection with this Agreement, regardless of the theory of liability.",
    "Governing Law: This Agreement shall be governed by and construed in accordance with the laws applicable in the Kingdom of Saudi Arabia, without regard to its conflict of laws principles.",
    "Notices: Any formal notice required under this Agreement shall be delivered in writing via registered mail or confirmed electronic transmission to the official corporate addresses designated by each party."
  ]
}
